CREATE OR REPLACE FUNCTION public.sanitize_text()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    IF TG_TABLE_NAME = 'menu_items' THEN
        IF NEW.name IS NOT NULL THEN
            NEW.name := regexp_replace(NEW.name, '<[^>]*>', '', 'g');
        END IF;

        IF NEW.description IS NOT NULL THEN
            NEW.description := regexp_replace(NEW.description, '<[^>]*>', '', 'g');
        END IF;

        IF NEW.image_url IS NOT NULL AND NEW.image_url !~* '^https?://' THEN
            NEW.image_url := NULL;
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'restaurant_settings' THEN
        IF NEW.restaurant_name IS NOT NULL THEN
            NEW.restaurant_name := regexp_replace(NEW.restaurant_name, '<[^>]*>', '', 'g');
        END IF;

        IF NEW.logo_url IS NOT NULL AND NEW.logo_url !~* '^https?://' THEN
            NEW.logo_url := NULL;
        END IF;
    END IF;

    IF TG_TABLE_NAME = 'service_tickets' THEN
        IF NEW.request_type IS NOT NULL THEN
            NEW.request_type := regexp_replace(NEW.request_type, '<[^>]*>', '', 'g');
        END IF;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.advance_order_status(p_order_id uuid, p_next_status text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_order public.orders%ROWTYPE;
  updated_order public.orders%ROWTYPE;
BEGIN
  IF (SELECT auth.uid()) IS NULL THEN
    RAISE EXCEPTION 'authentication required' USING errcode = '42501';
  END IF;

  SELECT * INTO current_order
  FROM public.orders
  WHERE id = p_order_id
  FOR UPDATE;

  IF NOT FOUND OR NOT ting_private.can_manage_tenant(current_order.tenant_id) THEN
    RAISE EXCEPTION 'order unavailable' USING errcode = '42501';
  END IF;

  IF NOT (
    (current_order.status = 'submitted' AND p_next_status = 'accepted') OR
    (current_order.status = 'accepted' AND p_next_status = 'preparing') OR
    (current_order.status = 'preparing' AND p_next_status = 'ready') OR
    (current_order.status = 'ready' AND p_next_status = 'completed')
  ) THEN
    RAISE EXCEPTION 'invalid order status transition' USING errcode = '23514';
  END IF;

  UPDATE public.orders
  SET
    status = p_next_status,
    accepted_at = CASE WHEN p_next_status = 'accepted' THEN now() ELSE accepted_at END,
    preparing_at = CASE WHEN p_next_status = 'preparing' THEN now() ELSE preparing_at END,
    ready_at = CASE WHEN p_next_status = 'ready' THEN now() ELSE ready_at END,
    completed_at = CASE WHEN p_next_status = 'completed' THEN now() ELSE completed_at END,
    updated_at = now()
  WHERE id = current_order.id
  RETURNING * INTO updated_order;

  RETURN updated_order;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.assign_service_ticket_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  routed_client_slug text;
BEGIN
  IF tg_table_schema <> 'public'
     OR tg_table_name <> 'service_tickets'
     OR tg_when <> 'BEFORE'
     OR tg_level <> 'ROW'
     OR tg_op NOT IN ('INSERT', 'UPDATE') THEN
    RAISE EXCEPTION 'assign_service_ticket_tenant may only run as the approved public.service_tickets row trigger'
      USING errcode = '42501';
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF new.id IS DISTINCT FROM old.id
       OR new.tenant_id IS DISTINCT FROM old.tenant_id
       OR new.client_slug IS DISTINCT FROM old.client_slug
       OR new.table_number IS DISTINCT FROM old.table_number
       OR new.request_type IS DISTINCT FROM old.request_type
       OR new.created_at IS DISTINCT FROM old.created_at THEN
      RAISE EXCEPTION 'service ticket request details and ownership are immutable'
        USING errcode = '23514';
    END IF;
    RETURN new;
  END IF;

  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL THEN
    RAISE EXCEPTION 'service ticket insert requires a valid tenant route'
      USING errcode = '23514';
  END IF;

  SELECT tenant.client_slug
    INTO routed_client_slug
    FROM public.tenants tenant
   WHERE tenant.id = routed_tenant_id;

  IF new.tenant_id IS NOT NULL AND new.tenant_id <> routed_tenant_id THEN
    RAISE EXCEPTION 'tenant_id does not match the request route'
      USING errcode = '23514';
  END IF;
  IF new.client_slug IS NOT NULL AND new.client_slug <> routed_client_slug THEN
    RAISE EXCEPTION 'client_slug does not match the request route'
      USING errcode = '23514';
  END IF;

  new.tenant_id := routed_tenant_id;
  new.client_slug := routed_client_slug;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.assign_tenant_id_from_client_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    resolved_tenant_id UUID;
BEGIN
    IF TG_OP <> 'INSERT'
       OR TG_TABLE_SCHEMA <> 'public'
       OR TG_TABLE_NAME NOT IN ('menu_items', 'menu_events') THEN
        RAISE EXCEPTION
            'assign_tenant_id_from_client_slug may only run for approved INSERT triggers';
    END IF;

    IF NEW.client_slug IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT tenant.id
    INTO resolved_tenant_id
    FROM public.tenants AS tenant
    WHERE tenant.client_slug = NEW.client_slug;

    IF NEW.tenant_id IS NULL THEN
        NEW.tenant_id := resolved_tenant_id;

    ELSIF resolved_tenant_id IS NULL
          OR NEW.tenant_id <> resolved_tenant_id THEN
        RAISE EXCEPTION
            'tenant_id does not match client_slug'
            USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.confirm_payment_attempt(p_attempt_id uuid, p_provider text, p_provider_payment_id text, p_confirmed_amount numeric, p_currency text)
 RETURNS payment_attempts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  attempt public.payment_attempts%ROWTYPE;
  updated_attempt public.payment_attempts%ROWTYPE;
  normalized_amount numeric(12,2);
  paid numeric(12,2);
  order_total numeric(12,2);
BEGIN
  normalized_amount := round(p_confirmed_amount,2);
  SELECT * INTO attempt
  FROM public.payment_attempts
  WHERE id = p_attempt_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'payment attempt unavailable' USING errcode='42501'; END IF;

  IF attempt.status = 'succeeded' THEN
    IF attempt.provider = p_provider
       AND attempt.provider_payment_id = p_provider_payment_id
       AND attempt.confirmed_amount = normalized_amount
       AND attempt.currency = upper(p_currency) THEN
      RETURN attempt;
    END IF;
    RAISE EXCEPTION 'payment confirmation mismatch' USING errcode='23514';
  END IF;

  IF attempt.status NOT IN ('created','pending') THEN
    RAISE EXCEPTION 'payment attempt is not confirmable' USING errcode='23514';
  END IF;
  IF normalized_amount IS NULL OR normalized_amount <= 0 OR normalized_amount <> attempt.requested_amount THEN
    RAISE EXCEPTION 'confirmed amount mismatch' USING errcode='23514';
  END IF;
  IF upper(COALESCE(p_currency,'')) <> attempt.currency THEN
    RAISE EXCEPTION 'currency mismatch' USING errcode='23514';
  END IF;

  SELECT total INTO order_total
  FROM public.orders
  WHERE id=attempt.order_id AND tenant_id=attempt.tenant_id
  FOR UPDATE;

  SELECT COALESCE(round(sum(amount),2),0) INTO paid
  FROM public.payment_allocations
  WHERE tenant_id=attempt.tenant_id AND order_id=attempt.order_id;

  IF paid + normalized_amount > order_total THEN
    RAISE EXCEPTION 'payment would exceed order total' USING errcode='23514';
  END IF;

  UPDATE public.payment_attempts
  SET provider = lower(p_provider),
      provider_payment_id = p_provider_payment_id,
      confirmed_amount = normalized_amount,
      status = 'succeeded',
      confirmed_at = now(),
      updated_at = now()
  WHERE id = attempt.id
  RETURNING * INTO updated_attempt;

  INSERT INTO public.payment_allocations(tenant_id,order_id,payment_attempt_id,amount,currency)
  VALUES (attempt.tenant_id,attempt.order_id,attempt.id,normalized_amount,attempt.currency)
  ON CONFLICT (payment_attempt_id) DO NOTHING;

  SELECT COALESCE(round(sum(amount),2),0) INTO paid
  FROM public.payment_allocations
  WHERE tenant_id=attempt.tenant_id AND order_id=attempt.order_id;

  UPDATE public.orders
  SET payment_status = CASE
        WHEN paid <= 0 THEN 'unpaid'
        WHEN paid < total THEN 'partially_paid'
        ELSE 'paid'
      END,
      updated_at = now()
  WHERE id=attempt.order_id AND tenant_id=attempt.tenant_id;

  RETURN updated_attempt;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.create_payment_attempt(p_order_id uuid, p_requested_amount numeric, p_client_request_id uuid)
 RETURNS payment_attempts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  normalized_amount numeric(12,2);
  existing_attempt public.payment_attempts%ROWTYPE;
  created_attempt public.payment_attempts%ROWTYPE;
  balance record;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL THEN
    RAISE EXCEPTION 'payment attempt requires a valid tenant route' USING errcode = '23514';
  END IF;
  IF p_order_id IS NULL OR p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'order_id and client_request_id are required' USING errcode = '23514';
  END IF;

  normalized_amount := round(p_requested_amount,2);
  IF normalized_amount IS NULL OR normalized_amount <= 0 THEN
    RAISE EXCEPTION 'payment amount must be positive' USING errcode = '23514';
  END IF;

  SELECT * INTO existing_attempt
  FROM public.payment_attempts
  WHERE tenant_id = routed_tenant_id
    AND client_request_id = p_client_request_id;
  IF FOUND THEN
    RETURN existing_attempt;
  END IF;

  PERFORM ting_private.expire_payment_reservations(routed_tenant_id, p_order_id);

  SELECT * INTO balance
  FROM ting_private.payment_balance(p_order_id, routed_tenant_id, true);

  IF balance.amount_due <= 0 THEN
    RAISE EXCEPTION 'order is already fully paid' USING errcode = '23514';
  END IF;
  IF normalized_amount > balance.amount_available THEN
    RAISE EXCEPTION 'payment amount exceeds currently available balance' USING errcode = '23514';
  END IF;

  BEGIN
    INSERT INTO public.payment_attempts(
      tenant_id, order_id, client_request_id, requested_amount,
      currency, status, reservation_expires_at
    ) VALUES (
      routed_tenant_id, p_order_id, p_client_request_id, normalized_amount,
      'AUD', 'created', now() + interval '10 minutes'
    )
    RETURNING * INTO created_attempt;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO created_attempt
    FROM public.payment_attempts
    WHERE tenant_id = routed_tenant_id
      AND client_request_id = p_client_request_id;
    IF NOT FOUND THEN RAISE; END IF;
  END;

  RETURN created_attempt;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.issue_table_access_context(p_table_number text)
 RETURNS TABLE(context_id uuid, table_number text, token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  normalized_table text;
  raw_token text;
  inserted_id uuid;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL
     OR (SELECT auth.uid()) IS NULL
     OR NOT ting_private.can_manage_tenant(routed_tenant_id) THEN
    RAISE EXCEPTION 'tenant management authorization required' USING errcode = '42501';
  END IF;
  normalized_table := trim(COALESCE(p_table_number, ''));
  IF normalized_table !~ '^[A-Za-z0-9 _-]{1,20}$' THEN
    RAISE EXCEPTION 'invalid table context' USING errcode = '23514';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(routed_tenant_id::text || ':' || normalized_table, 0));
  raw_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO public.table_access_contexts (tenant_id, table_number, token_hash, created_by)
  VALUES (routed_tenant_id, normalized_table, extensions.digest(raw_token, 'sha256'), (SELECT auth.uid()))
  RETURNING id INTO inserted_id;
  RETURN QUERY SELECT inserted_id, normalized_table, raw_token;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.payment_balance(p_order_id uuid, p_tenant_id uuid, p_lock boolean DEFAULT false)
 RETURNS TABLE(order_total numeric, amount_paid numeric, amount_reserved numeric, amount_due numeric, amount_available numeric, payment_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_order public.orders%ROWTYPE;
  paid numeric(12,2);
  reserved numeric(12,2);
BEGIN
  IF p_lock THEN
    SELECT * INTO current_order
    FROM public.orders
    WHERE id = p_order_id AND tenant_id = p_tenant_id
    FOR UPDATE;
  ELSE
    SELECT * INTO current_order
    FROM public.orders
    WHERE id = p_order_id AND tenant_id = p_tenant_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'order unavailable' USING errcode = '42501';
  END IF;

  SELECT COALESCE(round(sum(a.amount),2),0)
  INTO paid
  FROM public.payment_allocations a
  WHERE a.tenant_id = p_tenant_id
    AND a.order_id = p_order_id;

  SELECT COALESCE(round(sum(a.requested_amount),2),0)
  INTO reserved
  FROM public.payment_attempts a
  WHERE a.tenant_id = p_tenant_id
    AND a.order_id = p_order_id
    AND a.status IN ('created','pending')
    AND a.reservation_expires_at > now();

  order_total := current_order.total;
  amount_paid := paid;
  amount_reserved := reserved;
  amount_due := greatest(round(current_order.total - paid,2),0);
  amount_available := greatest(round(current_order.total - paid - reserved,2),0);
  payment_status := CASE
    WHEN paid <= 0 THEN 'unpaid'
    WHEN paid < current_order.total THEN 'partially_paid'
    ELSE 'paid'
  END;
  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.request_tenant_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE headers jsonb; slug text;
BEGIN
  BEGIN
    headers := nullif(current_setting('request.headers', true), '')::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN RETURN NULL;
  END;
  slug := headers ->> 'x-client-slug';
  IF slug IS NULL OR slug !~ '^[A-Za-z0-9_-]{1,80}$' THEN RETURN NULL; END IF;
  RETURN (SELECT id FROM public.tenants WHERE client_slug = slug);
END $function$

CREATE OR REPLACE FUNCTION ting_private.revoke_table_access_context(p_context_id uuid)
 RETURNS TABLE(context_id uuid, table_number text, revoked_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL
     OR (SELECT auth.uid()) IS NULL
     OR NOT ting_private.can_manage_tenant(routed_tenant_id) THEN
    RAISE EXCEPTION 'tenant management authorization required' USING errcode = '42501';
  END IF;
  RETURN QUERY
  UPDATE public.table_access_contexts AS context
  SET revoked_at = COALESCE(context.revoked_at, pg_catalog.clock_timestamp())
  WHERE context.id = p_context_id AND context.tenant_id = routed_tenant_id
  RETURNING context.id, context.table_number, context.revoked_at;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'table access context unavailable' USING errcode = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands() WHERE command_tag IN ('CREATE TABLE','CREATE TABLE AS','SELECT INTO') AND object_type IN ('table','partitioned table')
  LOOP
    IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security',cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %',cmd.object_identity;
      EXCEPTION WHEN OTHERS THEN
        RAISE LOG 'rls_auto_enable: failed to enable RLS on %',cmd.object_identity;
      END;
    ELSE
      RAISE LOG 'rls_auto_enable: skip % (schema: %)',cmd.object_identity,cmd.schema_name;
    END IF;
  END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION ting_private.rotate_table_access_context(p_table_number text)
 RETURNS TABLE(context_id uuid, table_number text, token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  normalized_table text;
  raw_token text;
  inserted_id uuid;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL
     OR (SELECT auth.uid()) IS NULL
     OR NOT ting_private.can_manage_tenant(routed_tenant_id) THEN
    RAISE EXCEPTION 'tenant management authorization required' USING errcode = '42501';
  END IF;
  normalized_table := trim(COALESCE(p_table_number, ''));
  IF normalized_table !~ '^[A-Za-z0-9 _-]{1,20}$' THEN
    RAISE EXCEPTION 'invalid table context' USING errcode = '23514';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(routed_tenant_id::text || ':' || normalized_table, 0));
  UPDATE public.table_access_contexts AS context
  SET revoked_at = pg_catalog.clock_timestamp()
  WHERE context.tenant_id = routed_tenant_id
    AND context.table_number = normalized_table
    AND context.revoked_at IS NULL;
  raw_token := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO public.table_access_contexts (tenant_id, table_number, token_hash, created_by)
  VALUES (routed_tenant_id, normalized_table, extensions.digest(raw_token, 'sha256'), (SELECT auth.uid()))
  RETURNING id INTO inserted_id;
  RETURN QUERY SELECT inserted_id, normalized_table, raw_token;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.routing_client_slug()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE headers jsonb; slug text;
BEGIN
  BEGIN
    headers := nullif(current_setting('request.headers', true), '')::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN RETURN NULL;
  END;
  IF headers IS NULL THEN RETURN 'the-bistro'; END IF;
  IF jsonb_typeof(headers) <> 'object' THEN RETURN NULL; END IF;
  IF NOT headers ? 'x-client-slug' THEN RETURN 'the-bistro'; END IF;
  slug := headers ->> 'x-client-slug';
  IF slug IS NULL OR slug !~ '^[A-Za-z0-9_-]{1,80}$' THEN RETURN NULL; END IF;
  RETURN slug;
END $function$

CREATE OR REPLACE FUNCTION ting_private.submit_order(p_table_number text, p_client_request_id uuid, p_items jsonb, p_table_token text)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  normalized_table text;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL THEN
    RAISE EXCEPTION 'order submission requires a valid tenant route'
      USING errcode = '23514';
  END IF;

  normalized_table := trim(COALESCE(p_table_number, ''));
  IF NOT ting_private.table_access_context_is_valid(
    routed_tenant_id,
    normalized_table,
    p_table_token
  ) THEN
    RAISE EXCEPTION 'valid table access context required'
      USING errcode = '42501';
  END IF;

  RETURN ting_private.submit_order_unverified(
    normalized_table,
    p_client_request_id,
    p_items
  );
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.submit_order_unverified(p_table_number text, p_client_request_id uuid, p_items jsonb)
 RETURNS orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  normalized_table text;
  item_count integer;
  request_row record;
  menu_row public.menu_items%ROWTYPE;
  unit_price numeric(12,2);
  computed_subtotal numeric(12,2) := 0;
  existing_order public.orders%ROWTYPE;
  created_order public.orders%ROWTYPE;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL THEN
    RAISE EXCEPTION 'order submission requires a valid tenant route'
      USING errcode = '23514';
  END IF;

  normalized_table := trim(COALESCE(p_table_number, ''));
  IF normalized_table !~ '^[A-Za-z0-9 _-]{1,20}$' THEN
    RAISE EXCEPTION 'invalid table context' USING errcode = '23514';
  END IF;

  IF p_client_request_id IS NULL THEN
    RAISE EXCEPTION 'client_request_id is required' USING errcode = '23514';
  END IF;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'items must be a JSON array' USING errcode = '23514';
  END IF;

  item_count := jsonb_array_length(p_items);
  IF item_count < 1 OR item_count > 50 THEN
    RAISE EXCEPTION 'order must contain between 1 and 50 line items' USING errcode = '23514';
  END IF;

  SELECT * INTO existing_order
  FROM public.orders
  WHERE tenant_id = routed_tenant_id
    AND client_request_id = p_client_request_id;

  IF FOUND THEN
    RETURN existing_order;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.ting11_order_lines (
    menu_item_id uuid PRIMARY KEY,
    item_name text NOT NULL,
    unit_price numeric(12,2) NOT NULL,
    quantity integer NOT NULL,
    line_total numeric(12,2) NOT NULL
  ) ON COMMIT DROP;
  TRUNCATE pg_temp.ting11_order_lines;

  FOR request_row IN
    SELECT
      x.menu_item_id,
      sum(x.quantity)::integer AS quantity
    FROM (
      SELECT
        CASE
          WHEN item ? 'menu_item_id' AND (item->>'menu_item_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (item->>'menu_item_id')::uuid
          ELSE NULL
        END AS menu_item_id,
        CASE
          WHEN item ? 'quantity' AND (item->>'quantity') ~ '^[0-9]+$'
          THEN (item->>'quantity')::integer
          ELSE NULL
        END AS quantity
      FROM jsonb_array_elements(p_items) AS item
    ) x
    GROUP BY x.menu_item_id
  LOOP
    IF request_row.menu_item_id IS NULL
       OR request_row.quantity IS NULL
       OR request_row.quantity < 1
       OR request_row.quantity > 99 THEN
      RAISE EXCEPTION 'invalid order item payload' USING errcode = '23514';
    END IF;

    SELECT * INTO menu_row
    FROM public.menu_items
    WHERE id = request_row.menu_item_id
      AND tenant_id = routed_tenant_id
    FOR SHARE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'menu item is unavailable for this restaurant' USING errcode = '23514';
    END IF;

    IF COALESCE(menu_row.is_out_of_stock, false) THEN
      RAISE EXCEPTION 'menu item is out of stock' USING errcode = '23514';
    END IF;

    unit_price := round(
      CASE
        WHEN COALESCE(menu_row.is_promo, false) AND menu_row.promo_price IS NOT NULL
          THEN menu_row.promo_price
        ELSE menu_row.price
      END,
      2
    );

    INSERT INTO pg_temp.ting11_order_lines(menu_item_id, item_name, unit_price, quantity, line_total)
    VALUES (
      menu_row.id,
      menu_row.name,
      unit_price,
      request_row.quantity,
      round(unit_price * request_row.quantity, 2)
    );
  END LOOP;

  SELECT COALESCE(round(sum(line_total), 2), 0)
  INTO computed_subtotal
  FROM pg_temp.ting11_order_lines;

  BEGIN
    INSERT INTO public.orders (
      tenant_id,
      table_number,
      status,
      subtotal,
      total,
      client_request_id
    )
    VALUES (
      routed_tenant_id,
      normalized_table,
      'submitted',
      computed_subtotal,
      computed_subtotal,
      p_client_request_id
    )
    RETURNING * INTO created_order;
  EXCEPTION WHEN unique_violation THEN
    SELECT * INTO created_order
    FROM public.orders
    WHERE tenant_id = routed_tenant_id
      AND client_request_id = p_client_request_id;
    IF NOT FOUND THEN
      RAISE;
    END IF;
    RETURN created_order;
  END;

  INSERT INTO public.order_items (
    tenant_id,
    order_id,
    menu_item_id,
    item_name_snapshot,
    unit_price_snapshot,
    quantity,
    line_total
  )
  SELECT
    routed_tenant_id,
    created_order.id,
    line.menu_item_id,
    line.item_name,
    line.unit_price,
    line.quantity,
    line.line_total
  FROM pg_temp.ting11_order_lines line;

  RETURN created_order;
END;
$function$

CREATE OR REPLACE FUNCTION ting_private.submit_service_ticket(p_id uuid, p_table_number text, p_request_type text, p_table_token text)
 RETURNS service_tickets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  routed_tenant_id uuid;
  normalized_table text;
  normalized_request_type text;
  inserted_ticket public.service_tickets;
BEGIN
  routed_tenant_id := ting_private.request_tenant_id();
  IF routed_tenant_id IS NULL THEN
    RAISE EXCEPTION 'service ticket submission requires a valid tenant route'
      USING errcode = '23514';
  END IF;

  IF p_id IS NULL THEN
    RAISE EXCEPTION 'service ticket id is required'
      USING errcode = '23502';
  END IF;

  normalized_table := trim(COALESCE(p_table_number, ''));
  IF normalized_table !~ '^[A-Za-z0-9 _-]{1,20}$' THEN
    RAISE EXCEPTION 'invalid table context'
      USING errcode = '23514';
  END IF;

  IF NOT ting_private.table_access_context_is_valid(
    routed_tenant_id,
    normalized_table,
    p_table_token
  ) THEN
    RAISE EXCEPTION 'valid table access context required'
      USING errcode = '42501';
  END IF;

  normalized_request_type := trim(COALESCE(p_request_type, ''));
  IF length(normalized_request_type) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'invalid service ticket request type'
      USING errcode = '23514';
  END IF;

  INSERT INTO public.service_tickets (
    id,
    table_number,
    request_type,
    status
  ) VALUES (
    p_id,
    normalized_table,
    normalized_request_type,
    'pending'
  )
  ON CONFLICT (id) DO NOTHING
  RETURNING * INTO inserted_ticket;

  IF inserted_ticket.id IS NULL THEN
    SELECT *
      INTO inserted_ticket
      FROM public.service_tickets ticket
     WHERE ticket.id = p_id;

    IF inserted_ticket.id IS NULL
       OR inserted_ticket.tenant_id <> routed_tenant_id
       OR inserted_ticket.table_number <> normalized_table
       OR inserted_ticket.request_type <> normalized_request_type THEN
      RAISE EXCEPTION 'service ticket id already exists with different request details'
        USING errcode = '23505';
    END IF;
  END IF;

  RETURN inserted_ticket;
END;
$function$
